ruleContent.content:
@js:
var javaImport = new JavaImporter();
javaImport.importPackage(Packages.java.lang, Packages.javax.crypto.spec, Packages.javax.crypto, Packages.java.util);
with (javaImport) {
    function decode(content) {
        var ivEncData = Base64.getDecoder().decode(String(content));
        var key = SecretKeySpec(String("242ccb8230d709e1").getBytes(), "AES");
        var iv = IvParameterSpec(Arrays.copyOfRange(ivEncData, 0, 16));
        var chipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        chipher.init(2, key, iv);
        return String(chipher.doFinal(Arrays.copyOfRange(ivEncData, 16, ivEncData.length)));
    }
}

var data = java.hexDecodeToString(result);
var parts = String(data).split('/');
var bid = String(java.get("bid") || '');
var chapterId = parts.length >= 1 ? String(parts[0]) : '';
var cmd5 = parts.length >= 2 ? String(parts[1]) : '';
if (!bid || !chapterId) {
    throw new Error("Missing bid or chapterId");
}

var headers = buildHeaders(java);

var params = { id: bid, chapterId: chapterId };
signParams(params, java);
var url = "https://api-ks.wtzw.com/api/v1/chapter/content?" + urlEncode(params);
var response = JSON.parse(java.ajax(url + "," + JSON.stringify({ headers: headers })));

var content = response.data && response.data.content;

if (!content) {
    var paramsShort = { id: bid, chapterId: chapterId, reader_agent: 1 };
    signParams(paramsShort, java);
    var urlShort = "https://api-ks.wtzw.com/api/v1/chapter/content?" + urlEncode(paramsShort);
    response = JSON.parse(java.ajax(urlShort + "," + JSON.stringify({ headers: headers })));
    content = response.data && response.data.content;
}

if (!content) {
    throw new Error("chapter content not found");
}

var qmText = decode(content);
if (qmText.indexOf('PK') === 0) {
    qmText = '此书籍无法阅读\n部分出版书籍epub/zⅰp无法解密';
}
var chapterMd5 = String((response.data && response.data.content_md5) || cmd5 || '');
try { if (typeof qmC_SetRuntime == 'function') qmC_SetRuntime(java, typeof source != 'undefined' ? source : null); } catch (runtimeError) {}
if (typeof qmC_AppendComments == 'function') {
    qmC_AppendComments.call(this, qmText, bid, chapterId, chapterMd5);
} else {
    qmText;
}

